package m8

const consolePMSpecFlowPageHTML = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PM Spec 工作流</title>
<style>
*{box-sizing:border-box}body{font:16px/1.5 system-ui,sans-serif;margin:0 auto;padding:16px;max-width:980px;color:#182230}h1,h2{line-height:1.2}section,article{border:1px solid #d0d5dd;border-radius:10px;padding:14px;margin:12px 0}label{display:block;margin:10px 0 4px}input,textarea,select,button{font:inherit;max-width:100%;padding:8px}input,textarea,select{width:100%}textarea{min-height:130px}button{min-height:44px;margin:5px 6px 0 0}button:disabled{opacity:.55}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.muted{color:#667085;font-size:.9rem}.error{color:#b42318}.ok{color:#067647}.item{background:#f7f8fa;padding:10px;border-radius:8px;margin:8px 0}.choices{display:flex;gap:16px;flex-wrap:wrap}.choices label{display:flex;align-items:center;gap:6px}.choices input{width:auto}#draft-list button{display:block;width:100%;text-align:left}#status{white-space:pre-wrap}@media(max-width:600px){body{padding:10px}.row{grid-template-columns:1fr}section{padding:11px}h1{font-size:1.5rem}}
</style><h1>Spec 草稿与审查</h1><p class="muted">自动保存只更新工作草稿；接受建议、转审和审查完成才会生成不可变修订。发生冲突时本页保留你的文本。</p>
<section><div class="row"><div><label for="draft-select">现有草稿</label><select id="draft-select"><option value="">选择草稿</option></select></div><div><label>&nbsp;</label><button id="new-draft">新建草稿</button><button id="reload">刷新</button></div></div></section>
<section id="editor" hidden><div class="muted" id="draft-meta"></div><label for="title">标题</label><input id="title"><label for="body">正文</label><textarea id="body"></textarea><div class="row"><div><label for="acceptance">验收标准 JSON</label><textarea id="acceptance" rows="4">{"criteria":[]}</textarea></div><div><label for="sources">来源引用 JSON</label><textarea id="sources" rows="4">[]</textarea></div></div><label for="norms">规范锚点 JSON</label><textarea id="norms" rows="3">[]</textarea><div class="muted" id="save-state" role="status">未保存</div><div id="conflict-box" hidden class="item" role="alert"><strong>检测到并发编辑或保存结果未知</strong><p>本地文字仍保留，自动保存已暂停。选择载入服务器版本，或先手动合并后明确提交本地文本。</p><button id="use-server">载入服务器版本</button><button id="submit-local">我已合并，提交当前本地文本</button><button id="retry-server">重新读取服务器版本</button></div></section>
<section id="actions" hidden><h2>Agent 协助与审查</h2><div class="row"><div><label for="agent">本人的在线 Agent</label><select id="agent"></select></div><div><label>&nbsp;</label><button id="assist">Agent 协助（审查当前正文）</button></div></div><div id="assist-box" hidden><p id="assist-state"></p><div id="items"></div><button id="save-decisions">保存本轮表态</button><button id="accept-selected">接受所选建议并固化新修订</button></div><div id="review-controls"><div class="row"><div><label for="recipient">转给他人审查</label><select id="recipient"></select></div><div><label>&nbsp;</label><button id="transfer">转审并锁定正文</button></div></div><button id="complete-review">审查完成</button><label for="objection">退回异议</label><textarea id="objection" rows="2"></textarea><button id="return-review">退回原编辑者</button><button id="finalize">定稿并进入拆解</button></div><p class="muted" id="status" role="status"></p></section>
<script>
window.pmPrincipal="__PM_PRINCIPAL__";
(()=>{'use strict';const $=id=>document.getElementById(id);let draft=null,pendingSpecID='',timer=0,saving=Promise.resolve(),assist=null,agents=[],editors=[],dirty=false,saveBlocked=false,conflictRemote=null;
async function req(url,method='GET',body){const r=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(!r.ok)throw Error((await r.text()).trim()||('HTTP '+r.status));return r.status===204?null:r.json()}
function setStatus(text,kind=''){ $('status').textContent=text;$('status').className=kind; }
function payload(){if(!draft&&!pendingSpecID)pendingSpecID='pm-'+crypto.randomUUID();return {spec_id:draft?draft.spec_id:pendingSpecID,title:$('title').value,content_markdown:$('body').value,acceptance_json:$('acceptance').value||'{"criteria":[]}',input_anchors_json:'[]',source_refs_json:$('sources').value||'[]',norm_anchors_json:$('norms').value||'[]',expected_version:draft?draft.version:0,expected_sha256:draft?draft.content_sha256:''}}
function renderMeta(){ $('draft-meta').textContent=draft?('状态 '+draft.state+' · 工作草稿版本 '+draft.version+' · SHA256 '+draft.content_sha256.slice(0,16)+'… · 基础修订 '+draft.base_revision):''; }
function setConflict(remote){conflictRemote=remote||null;saveBlocked=true;$('conflict-box').hidden=false;$('draft-select').disabled=true;$('new-draft').disabled=true;$('reload').disabled=true;$('save-state').textContent='并发冲突／结果未知：自动保存暂停';$('save-state').className='error';}
function clearConflict(){conflictRemote=null;saveBlocked=false;$('conflict-box').hidden=true;$('draft-select').disabled=false;$('new-draft').disabled=false;$('reload').disabled=false;}
function sameDraft(d,p){return d&&d.spec_id===p.spec_id&&d.title===p.title&&d.content_markdown===p.content_markdown&&d.acceptance_json===p.acceptance_json&&d.source_refs_json===p.source_refs_json&&d.norm_anchors_json===p.norm_anchors_json;}
async function saveNow(){if(!dirty||saveBlocked)return;if(!draft&& !$('title').value.trim()&&!$('body').value.trim())return;const p=payload();if(!draft)draft={spec_id:p.spec_id,version:0,content_sha256:'',state:'editing'};$('save-state').textContent='正在保存…';try{const next=await req('/api/console/pm-spec-flow/drafts','POST',p);draft=next;pendingSpecID=next.spec_id;dirty=false;renderMeta();$('save-state').textContent='已自动保存';$('save-state').className='ok';await refreshList(false);}catch(e){let remote=null;try{remote=await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(p.spec_id));}catch(_){}if(sameDraft(remote,p)){draft=remote;pendingSpecID=p.spec_id;dirty=false;clearConflict();renderMeta();$('save-state').textContent='保存回执丢失；已读取并确认服务器内容一致';$('save-state').className='ok';return;}setConflict(remote);setStatus(e.message,'error');} }
function scheduleSave(){dirty=true;if(saveBlocked)return;if(!draft&& !$('title').value.trim()&&!$('body').value.trim())return;$('save-state').textContent='待自动保存…';clearTimeout(timer);timer=setTimeout(()=>{saving=saving.then(saveNow)},700)}
async function flushSave(){if(saveBlocked)throw Error('存在未解决的保存冲突；本地文本仍保留');clearTimeout(timer);saving=saving.then(saveNow);await saving;if(dirty||saveBlocked)throw Error('草稿未保存；本地文本仍保留，请先处理冲突')}
function fill(d){draft=d;pendingSpecID=d.spec_id;assist=null;$('assist-box').hidden=true;$('items').replaceChildren();dirty=false;$('editor').hidden=false;$('actions').hidden=false;$('title').value=d.title;$('body').value=d.content_markdown;$('acceptance').value=d.acceptance_json;$('sources').value=d.source_refs_json;$('norms').value=d.norm_anchors_json;renderMeta();const editor=d.current_editor_id===window.pmPrincipal;const editable=editor&&d.state==='editing';const reviewer=editor&&d.state==='review';['title','body','acceptance','sources','norms'].forEach(k=>$(k).readOnly=!editable);$('save-state').textContent=editable?'自动保存就绪':'当前为只读审查';$('review-controls').hidden=!(editable||reviewer||d.state==='review_complete');$('transfer').hidden=!editable;$('recipient').disabled=!editable;$('assist').hidden=!(editable||reviewer);$('complete-review').hidden=!(editable||reviewer);$('return-review').hidden=!reviewer;$('objection').hidden=!reviewer;$('finalize').hidden=d.state!=='review_complete'||!editor;loadAssistAgents();loadEditors();}
async function refreshList(selectCurrent=true){if(saveBlocked)throw Error('先解决当前草稿冲突');const data=await req('/api/console/pm-spec-flow/drafts'),sel=$('draft-select'),old=selectCurrent&&draft?draft.spec_id:sel.value;sel.replaceChildren(new Option('选择草稿',''));for(const d of data.drafts||[]){const o=new Option((d.title||'(无标题)')+' · '+d.state+' · '+d.spec_id,d.spec_id);sel.append(o)}if(old&&Array.from(sel.options).some(o=>o.value===old))sel.value=old;}
async function openDraft(id){if(!id)return;try{fill(await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(id)));setStatus('');}catch(e){setStatus(e.message,'error')}}
async function loadAssistAgents(){try{const data=await req('/api/console/agents'),sel=$('agent');agents=(data.agents||[]);sel.replaceChildren();agents.forEach(a=>{if(!a.id)return;sel.append(new Option(a.session+(a.online?'':' · 离线'),a.id));sel.options[sel.options.length-1].disabled=!a.online});if(!agents.some(a=>a.online))$('assist').disabled=true;else $('assist').disabled=false;}catch(e){setStatus('无法读取 Agent：'+e.message,'error')}}
async function loadEditors(){try{const data=await req('/api/console/spec-editors'),sel=$('recipient');editors=data.editors||[];sel.replaceChildren(...editors.map(e=>new Option(e.display_name,e.id)));}catch(e){setStatus('无法读取审查接收人：'+e.message,'error')}}
function renderItems(result){const box=$('items');box.replaceChildren();const all=[...(result.suggestions||[]).map(x=>({...x,category:'建议'})),...(result.review_questions||[]).map(x=>({...x,kind:'question',payload:{text:x.question},category:'审查问题'}))];if(!all.length){box.textContent='本轮没有建议或审查问题。';return}all.forEach(x=>{const card=document.createElement('article');card.className='item';const heading=document.createElement('strong');heading.textContent=x.category+' · '+x.kind+' · '+x.id;const pre=document.createElement('pre');pre.textContent=JSON.stringify(x.payload,null,2);const choices=document.createElement('div');choices.className='choices';const name='decision-'+x.id;for(const [value,label] of [['accept','接受'],['reject','不接受']]){const l=document.createElement('label'),i=document.createElement('input');i.type='radio';i.name=name;i.value=value;l.append(i,document.createTextNode(label));choices.append(l)}const reason=document.createElement('input');reason.placeholder='理由（可选）';reason.dataset.reason=x.id;card.append(heading,pre,choices,reason);box.append(card)});}
async function submitDecisions(){if(!assist)throw Error('没有当前 Agent 协助结果');const decisions=[];for(const x of [...(assist.suggestions||[]),...(assist.review_questions||[])]){const selected=document.querySelector('input[name="decision-'+CSS.escape(x.id)+'"]:checked');if(!selected)throw Error('请对每条建议／问题选择接受或不接受');decisions.push({item_id:x.id,outcome:selected.value,reason:document.querySelector('[data-reason="'+CSS.escape(x.id)+'"]').value})}await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(draft.spec_id)+'/assist/'+encodeURIComponent(assist.request_id)+'/decisions','POST',{decisions});}
async function pollAssist(requestID){for(let n=0;n<90;n++){await new Promise(r=>setTimeout(r,2000));const q=await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(draft.spec_id)+'/assist/'+encodeURIComponent(requestID));if(q.status==='completed'){assist=q.result;$('assist-state').textContent='协助结果绑定工作草稿 v'+q.working_version+'；正文变更后本结果失效。';$('assist-box').hidden=false;renderItems(assist);return}if(q.status!=='pending')throw Error('Agent 协助结束：'+q.status)}throw Error('等待 Agent 超时；请重新发起协助')}
$('new-draft').onclick=async()=>{if(saveBlocked)return setStatus('先解决当前草稿冲突；本地文字仍保留','error');try{await flushSave()}catch(e){return setStatus(e.message,'error')}draft=null;pendingSpecID='';assist=null;$('assist-box').hidden=true;$('items').replaceChildren();$('editor').hidden=false;$('actions').hidden=false;$('title').value='';$('body').value='';$('acceptance').value='{"criteria":[]}';$('sources').value='[]';$('norms').value='[]';$('draft-meta').textContent='新工作草稿尚未固化';$('save-state').textContent='输入后自动保存';$('review-controls').hidden=false;$('recipient').disabled=false;$('transfer').hidden=false;$('complete-review').hidden=false;$('return-review').hidden=true;$('objection').hidden=true;$('finalize').hidden=true;['title','body','acceptance','sources','norms'].forEach(k=>$(k).readOnly=false);dirty=false;clearConflict();loadAssistAgents();loadEditors()};
$('reload').onclick=async()=>{if(saveBlocked)return setStatus('先解决当前草稿冲突；本地文字仍保留','error');try{await flushSave();await refreshList(false)}catch(e){setStatus(e.message,'error')}};$('draft-select').onchange=async e=>{if(saveBlocked){e.target.value=draft?.spec_id||'';return}const next=e.target.value;try{await flushSave();if(next)await openDraft(next)}catch(err){e.target.value=draft?.spec_id||'';setStatus(err.message,'error')}};['title','body','acceptance','sources','norms'].forEach(k=>$(k).addEventListener('input',scheduleSave));
$('retry-server').onclick=async()=>{try{conflictRemote=await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(pendingSpecID||draft?.spec_id));setStatus('已重新读取服务器版本；选择载入或合并后提交。','ok')}catch(e){setStatus('读取服务器版本失败：'+e.message,'error')}};
$('use-server').onclick=()=>{if(!conflictRemote)return setStatus('尚未取得服务器版本，请先重新读取','error');fill(conflictRemote);clearConflict();setStatus('已载入服务器版本；本地副本已由你明确放弃。','ok')};
$('submit-local').onclick=async()=>{const attempted=draft;if(!conflictRemote&&(!attempted||attempted.version!==0))return setStatus('尚未取得服务器版本，不能安全提交；请先重新读取','error');if(conflictRemote){draft=conflictRemote;pendingSpecID=draft.spec_id}clearConflict();dirty=true;try{await saveNow();if(!saveBlocked&&!dirty){renderMeta();setStatus('本地文本已按最新服务器版本号明确提交。','ok')}}catch(e){setConflict(conflictRemote);setStatus(e.message,'error')}};
$('assist').onclick=async()=>{try{await flushSave();if(!draft)throw Error('先输入标题或正文');assist=null;$('assist-box').hidden=true;$('items').replaceChildren();const a=$('agent').value;if(!a)throw Error('选择本人的在线 Agent');const q=await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(draft.spec_id)+'/assist','POST',{agent_id:a,working_version:draft.version,content_sha256:draft.content_sha256});$('assist-box').hidden=false;$('assist-state').textContent='正在等待 Agent；请求最长 180 秒。';await pollAssist(q.request_id)}catch(e){setStatus(e.message,'error')}};
$('save-decisions').onclick=async()=>{try{await submitDecisions();setStatus('本轮逐条表态已保存；拒绝项不阻止继续编辑。','ok')}catch(e){setStatus(e.message,'error')}};
$('accept-selected').onclick=async()=>{try{await submitDecisions();const body={operation_id:crypto.randomUUID(),expected_version:draft.version,expected_sha256:draft.content_sha256,action:'accept_suggestions',assist_request_id:assist.request_id};await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(draft.spec_id)+'/freeze','POST',body);await openDraft(draft.spec_id);setStatus('已接受所选建议并固化新修订。','ok')}catch(e){setStatus(e.message,'error')}};
$('transfer').onclick=async()=>{try{await flushSave();if(!draft)throw Error('先输入标题或正文');if(!$('recipient').value)throw Error('选择审查接收人');const body={operation_id:crypto.randomUUID(),expected_version:draft.version,expected_sha256:draft.content_sha256,action:'transfer_review',target_principal:$('recipient').value};await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(draft.spec_id)+'/freeze','POST',body);await openDraft(draft.spec_id);setStatus('已转审，正文已锁定。','ok')}catch(e){setStatus(e.message,'error')}};
$('complete-review').onclick=async()=>{try{await flushSave();if(!assist)throw Error('请先对当前草稿运行一次新的 Agent 协助');await submitDecisions();const body={operation_id:crypto.randomUUID(),expected_version:draft.version,expected_sha256:draft.content_sha256,action:'complete_review',assist_request_id:assist.request_id};await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(draft.spec_id)+'/freeze','POST',body);await openDraft(draft.spec_id);setStatus('审查完成。可以定稿并进入拆解。','ok')}catch(e){setStatus(e.message,'error')}};
$('return-review').onclick=async()=>{try{await req('/api/console/pm-spec-flow/drafts/'+encodeURIComponent(draft.spec_id)+'/return','POST',{objection:$('objection').value});await openDraft(draft.spec_id);setStatus('已退回原编辑者。','ok')}catch(e){setStatus(e.message,'error')}};
$('finalize').onclick=async()=>{try{await req('/api/console/specs/'+encodeURIComponent(draft.spec_id)+'/workflow/finalize','POST');setStatus('已定稿，可进入现有任务拆解。','ok');await openDraft(draft.spec_id)}catch(e){setStatus(e.message,'error')}};
refreshList().catch(e=>setStatus(e.message,'error'));
})();
</script></html>`
